function toast(message,error=false){const div=document.createElement('div');div.className=`toast ${error?'error':''}`;div.setAttribute('role',error?'alert':'status');div.innerHTML=`${icon(error?'warning':'checkcircle')}<span>${esc(message)}</span>`;$('#toast-region').append(div);setTimeout(()=>div.remove(),6000);}
function modal(title,body,actions='',wide=false){const root=$('#modal-root');if(!root.innerHTML)modalReturnFocus=focusRecord();root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${actions?`<footer class="modal-actions">${actions}</footer>`:''}</section></div>`;$('.modal input,.modal textarea,.modal select,.modal button')?.focus({preventScroll:true});isolateAppForModal(true);}
function scheduleFormSignature(){const form=$('#schedule-form');if(!form)return null;return JSON.stringify(['schedule-name','schedule-template','schedule-frequency','schedule-start','schedule-timezone','schedule-scenario','schedule-input'].map(id=>$('#'+id)?.value??''));}
function updateScheduleEditorDirty(){if(!state.scheduleEditor)return false;const signature=scheduleFormSignature();if(signature!==null)state.scheduleEditor.dirty=signature!==state.scheduleEditor.initialSignature;return state.scheduleEditor.dirty;}
function confirmScheduleEditorDiscard(){if(!state.scheduleEditor)return true;updateScheduleEditorDirty();if(state.scheduleEditor.dirty&&!confirm('Discard your unsaved schedule changes?'))return false;state.scheduleEditor=null;return true;}
function closeModal(force=false){const root=$('#modal-root');if(!root?.innerHTML)return true;if(!force&&!confirmScheduleEditorDiscard())return false;state.scheduleEditor=null;root.innerHTML='';isolateAppForModal(false);const returnTo=modalReturnFocus;modalReturnFocus=null;setTimeout(()=>restoreFocus(returnTo),0);return true;}
function empty(title,description,ic='grid',action=''){return `<div class="empty">${icon(ic)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function setRoute(route,id){if(!confirmScheduleEditorDiscard())return false;if($('#modal-root')?.innerHTML)closeModal(true);state.contextMenu=null;if(route!=='studio')state.palette=false;state.route=route;state.runId=id||null;state.run=null;location.hash=id?`${route}/${id}`:route;render();if(route==='runs'&&id)loadRun(id);if(route==='schedules')refreshSchedules(true);if(route==='lab'){loadExperiments();loadSimulationLab();}if(route==='audit')loadAudit();if(route==='factory')loadFactory();if(route==='connections')loadConnectionCatalog();return true;}
function shell(){const selectedNav=state.route,syncLabel=state.pollStale?'Reconnecting':preview?'Explorable preview':'Local execution',themeLabel=state.theme==='dark'?'Switch to day mode':'Switch to night mode';return `<div class="app-shell"><a class="skip-link" href="#page-content">Skip to main content</a><aside class="navrail" aria-label="Primary navigation"><button class="brand-symbol" data-route="studio" aria-label="Axiom home">a</button><nav class="nav-items">${nav.map(([id,ic,label])=>`<button class="nav-item ${selectedNav===id?'active':''}" data-route="${id}" aria-label="${esc(label)}" ${selectedNav===id?'aria-current="page"':''}>${icon(ic)}<span class="nav-tooltip">${esc(label)}</span></button>`).join('')}</nav><div class="nav-bottom"><button class="nav-item" data-action="about" aria-label="About this local application">${icon('terminal')}<span class="nav-tooltip">Local workspace</span></button><span class="avatar" title="${esc(state.data.user.name)}">${esc(initials(state.data.user.name))}</span></div></aside><main class="app-main"><header class="global-header"><div class="breadcrumb"><span>Axiom workspace</span>${icon('chevron')}<strong>${esc(nav.find(n=>n[0]===state.route)?.[2]||'Studio')}</strong></div><div class="header-right"><button class="icon-btn theme-toggle" data-action="toggle-theme" aria-label="${themeLabel}" title="${themeLabel}" aria-pressed="${state.theme==='dark'}">${icon(state.theme==='dark'?'sun':'moon')}</button><span class="live-label ${state.pollStale?'stale':''}" role="status" aria-live="polite"><span class="dot"></span>${syncLabel}</span><div class="account-switch"><span class="avatar">${esc(initials(state.data.user.name))}</span><label for="account-switch">Development account<select id="account-switch" aria-label="Development account">${state.data.users.map(u=>`<option value="${esc(u.id)}" ${u.id===state.data.user.id?'selected':''}>${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label></div></div></header>${!preview&&state.pollStale?`<div class="sync-status" role="status" aria-live="polite">${icon('warning')}<span><strong>Live updates interrupted.</strong> Reconnecting; displayed run data may be stale.</span></div>`:''}<div class="page ${state.route==='studio'?'studio-page':''}" id="page-content" tabindex="-1">${page()}</div></main></div>`;}
function render(){if(!state.data)return;const oldScroll=$('.inspector-scroll')?.scrollTop||0;const renderKey=state.route+'/'+(state.runId||'');const samePage=state.renderedKey===renderKey;const focused=samePage&&document.activeElement?.closest?.('#app')?focusRecord():null;const pageScroll=samePage?$('.page')?.scrollTop||0:0;const graphScroll=samePage?{x:$('#runtime-graph-view')?.scrollLeft||0,y:$('#runtime-graph-view')?.scrollTop||0}:{x:0,y:0};$('#app').innerHTML=shell();state.renderedKey=renderKey;if($('.page'))$('.page').scrollTop=pageScroll;if($('#runtime-graph-view')){$('#runtime-graph-view').scrollLeft=graphScroll.x;$('#runtime-graph-view').scrollTop=graphScroll.y;}if(state.route==='studio'){bindCanvas();if(state.framingPending){requestAnimationFrame(()=>{frameCanvas();state.framingPending=false;});}if(state.fitPending){requestAnimationFrame(()=>{fitCanvas();state.fitPending=false;});}$('.inspector-scroll')&&( $('.inspector-scroll').scrollTop=oldScroll );}restoreFocus(focused);}
function templateLifecycleControls(){const admin=role()==='admin',archived=state.template?.status==='archived',inReview=state.template?.status==='in_review',lifecycleDisabled=!admin?'disabled title="Administrator role required"':inReview?'disabled title="Publish the submitted candidate before archiving it"':'';return `<span class="row" id="template-lifecycle-controls"><button class="btn subtle sm" data-action="duplicate-template" ${admin?'':'disabled title="Administrator role required"'}>Duplicate</button><button class="btn subtle sm" data-action="export-template">Export</button><button class="btn subtle sm" data-action="import-template" ${admin?'':'disabled title="Administrator role required"'}>Import</button><button class="btn ${archived?'':'danger'} sm" data-action="${archived?'restore-template':'archive-template'}" ${lifecycleDisabled}>${archived?'Restore':'Archive'}</button></span>`;}
function page(){switch(state.route){case'factory':return factoryPage();case'agents':return registry();case'runs':return state.runId?runDetail():runsPage();case'schedules':return schedulesPage();case'review':return reviewPage();case'lab':return labPage();case'connections':return connectionsPage();case'audit':return auditPage();default:return studio();}}
function editingBanner(previewMode=preview){
  if(previewMode)return '<div class="readonly-banner">Explorable interface preview · Design edits stay in this browser. Run the included local application for saved workflows, AI proposals, approvals, and execution.</div>';
  if(canEdit())return '';
  const administrator=(state.data.users||[]).find(user=>user.role==='admin');
  return `<div class="readonly-banner">${icon('lock')}<span><strong>${esc(human(role()))} view.</strong> ${esc(editReason())}</span>${administrator&&role()!=='admin'?`<button class="btn sm" data-switch-user="${esc(administrator.id)}">${icon('user')}Switch to editing account</button>`:''}</div>`;
}
function contextMenuItem(action,label,ic,{danger=false,disabled=false,shortcut='',reason=''}={}){
  return `<button class="context-menu-item ${danger?'danger':''}" role="menuitem" data-context-action="${esc(action)}" ${disabled?`disabled title="${esc(reason||editReason())}"`:''}>${icon(ic)}<span>${esc(label)}</span>${shortcut?`<kbd>${esc(shortcut)}</kbd>`:''}</button>`;
}
function contextMenuView(){
  const menu=state.contextMenu;if(!menu)return '';
  const style=`left:${Math.max(8,Number(menu.x)||8)}px;top:${Math.max(8,Number(menu.y)||8)}px`;
  if(menu.type==='node'){
    const node=state.template.nodes.find(item=>item.id===menu.nodeId),name=node?.label||'Workflow step',locked=!canEdit();
    return `<div class="context-menu" role="menu" aria-label="Actions for ${esc(name)}" style="${style}"><div class="context-menu-label">${esc(name)}</div>${contextMenuItem('configure-node','Configure step','settings')}${contextMenuItem('rename-node','Rename step','edit',{disabled:locked})}${contextMenuItem('add-after-node','Add connected step','plus',{disabled:locked})}${contextMenuItem('duplicate-node','Duplicate step','copy',{disabled:locked,shortcut:'⌘D'})}${contextMenuItem('connect-node','Connect from this step','link',{disabled:locked})}<div class="context-menu-separator"></div>${contextMenuItem('map-node','Map input fields','workflow',{disabled:locked})}${contextMenuItem('inspect-node-agent','Inspect agent contract','code')}${contextMenuItem('edit-node-agent','Edit reusable agent details','agent',{disabled:role()!=='admin',reason:'Administrator role required'})}<div class="context-menu-separator"></div>${contextMenuItem('remove-node','Remove from workflow','trash',{danger:true,disabled:locked,shortcut:'Del'})}</div>`;
  }
  if(menu.type==='edge')return `<div class="context-menu" role="menu" aria-label="Connection actions" style="${style}">${contextMenuItem('inspect-edge','Inspect connection','eye')}${contextMenuItem('remove-edge','Remove connection','trash',{danger:true,disabled:!canEdit()})}</div>`;
  return `<div class="context-menu" role="menu" aria-label="Canvas actions" style="${style}">${contextMenuItem('add-here','Add step here','plus',{disabled:!canEdit()})}${contextMenuItem('create-goal-agent','Create Goal Agent','spark',{disabled:role()!=='admin',reason:'Administrator role required'})}${contextMenuItem('register-agent','Register fixed capability alias','agent',{disabled:role()!=='admin',reason:'Administrator role required'})}<div class="context-menu-separator"></div>${contextMenuItem('fit-canvas','Fit workflow','fit')}${contextMenuItem('undo-canvas','Undo','undo',{disabled:!state.undo.length,shortcut:'⌘Z',reason:'Nothing to undo'})}${contextMenuItem('redo-canvas','Redo','redo',{disabled:!state.redo.length,shortcut:'⇧⌘Z',reason:'Nothing to redo'})}</div>`;
}
function studio(){const t=state.template;if(!t)return empty('No template available','The local service did not return a template.');return `<div class="studio-header"><div class="template-context"><div class="row"><label for="template-selector">Workflow template</label><select id="template-selector" aria-label="Select workflow template">${state.data.templates.map(item=>`<option value="${esc(item.id)}" ${item.id===t.id?'selected':''}>${esc(item.name)}${item.status==='archived'?' · archived':''}</option>`).join('')}</select><button class="btn subtle sm" data-action="new-template" ${role()==='admin'?'':'disabled title="Administrator role required"'}>${icon('plus')}New</button>${templateLifecycleControls()}</div><code>${esc(t.id)}</code></div><div class="studio-title-row"><div><div class="title-line"><h1><button class="title-edit" data-action="rename" ${disabledEdit()}>${esc(t.name)}</button></h1><span class="pill">Draft · r${esc(t.draftRevision||1)}</span></div><div class="studio-subtitle"><span>${esc(t.description||'Turn an incoming request into a reviewed, traceable outcome.')}</span><span class="tiny-line"></span><span>${t.publishedVersion?`v${esc(t.publishedVersion)} published`:'Unpublished'}</span></div></div><div class="studio-header-actions"><button class="btn save-btn ${state.dirty?'':'subtle'}" data-action="save" ${disabledEdit()}>${icon('save')}${state.dirty?'Save draft':'Saved'}</button><button class="btn" data-action="review-release">${icon('branch')}Review changes</button><button class="btn" data-action="new-schedule" ${t.publishedVersion&&t.status!=='archived'?'':'disabled title="Publish this workflow before scheduling it."'}>${icon('clock')}Schedule</button><button class="btn primary" data-action="start-run" ${t.status==='archived'?'disabled title="Restore this archived template before starting a task."':''}>${icon('play')}Run workflow</button></div></div><div class="studio-tabs"><div class="tabs"><button class="tab active" data-route="studio">${icon('workflow')}Design</button><button class="tab" data-route="lab">${icon('flask')}Rehearse</button><button class="tab" data-route="runs">${icon('activity')}Observe</button></div><div class="row"><button class="validation-chip" data-action="validate" title="Validate the complete graph">${icon(state.validation?.valid===false?'warning':'shield')}${state.validation?state.validation.valid?'Graph validated':'Review graph issues':'Validate before release'}</button><button class="icon-btn mobile-inspector-toggle" data-action="toggle-inspector" aria-label="Open configuration and AI panel">${icon('settings')}</button></div></div></div>${editingBanner()}<div class="studio-body"><section class="canvas-pane" aria-label="Workflow graph editor"><div class="canvas-toolbar"><div class="canvas-tools"><button class="btn sm" data-action="palette" ${disabledEdit()}>${icon('plus')}Add step</button><span class="toolbar-rule"></span><button class="icon-btn ${state.linkFrom?'active':''}" data-action="add-edge" aria-label="Connect two steps" title="Connect two steps" ${disabledEdit()}>${icon('link')}</button><button class="icon-btn" data-action="undo" aria-label="Undo change" title="Undo (Ctrl Z)" ${state.undo.length?'':'disabled'}>${icon('undo')}</button><button class="icon-btn" data-action="redo" aria-label="Redo change" title="Redo (Ctrl Shift Z)" ${state.redo.length?'':'disabled'}>${icon('redo')}</button><span class="toolbar-rule"></span><button class="icon-btn ${state.panel==='assistant'?'active':''}" data-action="assistant" aria-label="Open intent composer" title="Build from intent">${icon('spark')}</button></div><div class="graph-meta"><span><strong>${t.nodes.length}</strong> steps</span><span><strong>${t.edges.length}</strong> connections</span><span>AND joins</span></div></div><div class="canvas-viewport" id="canvas-viewport" tabindex="0" aria-label="Interactive workflow canvas. Drag the background to pan. Select a step to configure. Right-click for step and canvas actions. Use Fit graph to view all steps."><div class="canvas-help">${icon('workflow')}${state.linkFrom?'Select a destination step to connect. Escape to cancel.':'Drag to arrange · Select to inspect · Right-click for actions · Scroll to zoom'}</div>${!t.nodes.length?`<div class="blank-editor"><span class="blank-symbol">${icon('workflow')}</span><h2>Every process starts with one step.</h2><p>Add an intake agent, connect your capabilities, and define the human decisions that make this workflow yours.</p><button class="btn primary" data-action="palette" ${disabledEdit()}>${icon('plus')}Add your first step</button><small>No steps or external actions have been configured.</small></div>`:''}<div class="canvas-scene" id="canvas-scene" style="transform:translate(${state.panX}px,${state.panY}px) scale(${state.zoom})">${graph(t)}</div><div class="canvas-caption">${icon('shield')}Every action has a policy. Every outcome has evidence.</div></div>${state.palette?palette():''}<div class="canvas-controls"><button class="icon-btn" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span class="zoom-label">${Math.round(state.zoom*100)}%</span><button class="icon-btn" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><span class="toolbar-rule"></span><button class="icon-btn" data-action="fit" aria-label="Fit graph" title="Fit graph">${icon('fit')}</button></div><div class="canvas-bottom"><div class="canvas-legend"><span class="legend-item"><i class="legend-dot"></i>Automated</span><span class="legend-item"><i class="legend-dot human"></i>Human checkpoint</span><span class="legend-item"><i class="legend-dot write"></i>External action</span></div><span class="canvas-bottom-note">Draft changes never alter running versions</span></div></section>${state.contextMenu?contextMenuView():''}<aside class="inspector ${state.mobilePanel?'mobile-open':''} ${state.inspectorCollapsed?'collapsed':''}" aria-label="Step configuration and intent composer">${inspector()}</aside></div>`;}
function graph(t,run){const nodes=t.nodes||[];const runState=new Map(runNodes(run).map(n=>[n.nodeId,n.status]));return `<svg class="graph-svg" aria-label="Workflow connections" viewBox="0 0 1800 700"><defs><marker id="edge-arrow" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M1 1 7 4 1 7" fill="none" stroke="currentColor" stroke-width="1.3"/></marker></defs>${(t.edges||[]).map(e=>{const s=nodes.find(n=>n.id===e.source),d=nodes.find(n=>n.id===e.target);if(!s||!d)return '';const sx=Number(s.x)+210,sy=Number(s.y)+59,dx=Number(d.x),dy=Number(d.y)+59,bend=Math.max(45,Math.abs(dx-sx)/2);const cls=runState.get(e.source)==='succeeded'?'complete':runState.get(e.source)==='running'?'running':'';return `<path class="graph-edge ${cls}" d="M${sx} ${sy} C${sx+bend} ${sy},${dx-bend} ${dy},${dx} ${dy}" marker-end="url(#edge-arrow)" ${run?'':`data-edge="${esc(e.id)}" tabindex="0" role="button"`} aria-label="Connection from ${esc(s.label)} to ${esc(d.label)}.${run?'':' Select to inspect or remove.'}"><title>${esc(s.label)} → ${esc(d.label)}</title></path>`;}).join('')}</svg>${!run&&t.id==='customer-resolution'&&nodes.length===7&&nodes.every(n=>({intake:70,csr:330,policy:600,ownership:600,approval:880,ticket:1150,receipt:1420}[n.id]===Number(n.x)&&n.agentId===n.id))?'<div class="stage-label" style="left:70px"><span class="stage-number">01</span>Receive</div><div class="stage-label" style="left:330px"><span class="stage-number">02</span>Understand</div><div class="stage-label" style="left:600px"><span class="stage-number">03</span>Verify in parallel</div><div class="stage-label" style="left:880px"><span class="stage-number">04</span>Human control</div><div class="stage-label" style="left:1150px"><span class="stage-number">05</span>Deliver</div>':''}${nodes.map((n,i)=>{const a=agent(n.agentId),status=runState.get(n.id);return `<div class="graph-node ${!run&&state.selected===n.id?'selected':''} ${status||''} ${!run&&state.linkFrom&&state.linkFrom!==n.id?'connect-target':''}" style="left:${Number(n.x)||0}px;top:${Number(n.y)||0}px">${run?'':`<button type="button" class="node-menu-trigger" data-node-menu="${esc(n.id)}" aria-label="Open actions for ${esc(n.label)}" title="Step actions">${icon('more')}</button><button type="button" class="node-port in" data-port-in="${esc(n.id)}" aria-label="Connect to ${esc(n.label)}" tabindex="-1"></button>`}<button type="button" class="graph-node-select ${run?'runtime-node':''}" ${run?'data-step-data':'data-node'}="${esc(n.id)}" aria-label="${esc(n.label)}. ${esc(a.kind)}. ${esc(status||n.config?.executionMode||'automatic')} execution. Right-click or press Shift F10 for step actions."><span class="node-index">${String(i+1).padStart(2,'0')} / ${esc(a.kind==='human'?'HUMAN':a.sideEffects==='write'?'ACTION':'AGENT')}</span><span class="node-heading">${agentMark(a)}<span><span class="node-label">${esc(n.label||a.name)}</span><span class="node-kind">${esc(a.kind==='human'?'Human checkpoint':a.sideEffects==='write'?'Write capability':a.sideEffects==='read'?'Read capability':'Managed step')}</span></span></span><span class="node-footer"><span class="row node-status ${status||''}">${icon(status==='succeeded'?'checkcircle':status==='running'?'activity':n.config?.executionMode==='manual'?'user':a.kind==='human'?'shield':'bolt')}${esc(status?human(status):n.config?.executionMode==='manual'?'Manual execution':a.kind==='human'?'Approval required':'Automatic')}</span><span>${esc(a.version?`v${String(a.version).replace(/^v/,'')}`:'v1')}</span></span></button>${run?'':`<button type="button" class="node-port out" data-port-out="${esc(n.id)}" aria-label="Connect from ${esc(n.label)}" title="Connect from this step"></button>`}</div>`}).join('')}`;}
function palette(){const source=state.template.nodes.find(node=>node.id===state.pendingPlacement?.sourceId),title=source?`Add after ${source.label}`:'Add a step';return `<div class="palette"><div class="palette-header"><div><h3>${esc(title)}</h3>${source?'<small>The new step will be connected automatically.</small>':''}</div><button class="icon-btn" data-action="palette" aria-label="Close step palette">${icon('close')}</button></div><div class="palette-search">${icon('search')}<input id="palette-search" placeholder="Search agents…" aria-label="Search available agents"></div><div id="palette-agents">${state.data.agents.filter(a=>a.status!=='deprecated').map(a=>`<button class="palette-agent" data-add-agent="${esc(a.id)}" data-search="${esc(a.name.toLowerCase())}">${agentMark(a)}<span><strong>${esc(a.name)}</strong><small>${esc(human(a.kind))} · ${esc(a.sideEffects||'no')} side effects</small></span>${icon('plus')}</button>`).join('')}</div><button class="btn subtle sm palette-register" data-action="new-agent">${icon('plus')}Register a reusable agent</button><p class="small muted" style="padding-top:10px;line-height:1.6">Choose a capability, configure it in the inspector, then save the draft. Validation checks the complete workflow.</p></div>`;}
function inspector(){if(state.selected && state.panel==='node')return nodeInspector();return `<div class="inspector-top"><h3 class="row">${icon('spark')}Build from intent</h3><button class="icon-btn" data-action="toggle-inspector" aria-label="Close side panel">${icon('close')}</button></div><div class="inspector-scroll"><div class="inspector-intro"><span class="assistant-symbol">${icon('spark')}</span><div><h3>A design partner with boundaries</h3><p>Propose → inspect → apply</p></div></div><p class="inspector-copy">Describe the process you need. Review a structured change to this graph before anything is applied.</p><div class="intent-box"><textarea id="intent-input" placeholder="Before a ticket is created, require a reviewer to approve the case…" aria-label="Describe a workflow change">${esc(state.intent)}</textarea><div class="intent-box-footer"><span class="row">${icon('lock')}${esc(state.data.capabilities?.provider||'local-planner')}</span><button class="btn dark" data-action="plan" ${disabledEdit()}>Propose ${icon('arrow')}</button></div></div><div class="suggestions">${aiExamples.map((s,i)=>`<button class="suggestion" data-intent="${i}">${esc(s)}${icon('arrow')}</button>`).join('')}</div>${state.proposal?proposalView():`<div class="section-label">The contract comes first</div><div class="assurance-row">${icon('workflow')}Changes are explicit graph operations.</div><div class="assurance-row">${icon('shield')}Role and structural checks happen on the server.</div><div class="assurance-row">${icon('eye')}Nothing executes when you apply a proposal.</div><div class="divider"></div><div class="spread"><span class="uppercase muted">In this draft</span><span class="pill green">Versioned</span></div><div class="run-info"><label>Human checkpoints</label><strong>${state.template.nodes.filter(n=>agent(n.agentId).kind==='human'||n.config?.approvalRequired).length}</strong></div><div class="run-info"><label>Write-capable steps</label><strong>${state.template.nodes.filter(n=>agent(n.agentId).sideEffects==='write').length}</strong></div><div class="run-info"><label>Execution semantics</label><span>All dependencies</span></div><button class="btn sm" data-action="role-preview" style="margin-top:15px;width:100%">${icon('users')}Preview role access</button>`}</div><div class="inspector-footer">${icon('terminal')}${esc(state.data.capabilities?.provider||'local-planner')} · constrained proposals</div>`;}
function proposalView(){const p=state.proposal;return `<div class="proposal"><div class="proposal-header"><div class="spread"><h3>Proposed graph change</h3><span class="pill ${p.risk==='high'?'red':'blue'}">${esc(p.risk)} risk</span></div></div><div class="proposal-body"><p>${esc(p.summary)}</p>${(p.operations||[]).map(op=>`<div class="proposal-step"><span class="proposal-plus">${icon(op.op==='add_node'?'plus':'settings')}</span><div><strong>${esc(op.op==='add_node'?'Add step':'Update step')}: ${esc(op.node?.label||state.template.nodes.find(n=>n.id===op.nodeId)?.label||op.nodeId||'')}</strong><p>${esc(op.description||JSON.stringify(op.patch||{}))}</p></div></div>`).join('')}<div class="section-label" style="margin-top:16px">Assumptions to review</div>${(p.assumptions||[]).map(a=>`<div class="proposal-assumption">${esc(a)}</div>`).join('')||'<div class="proposal-assumption">No additional assumptions returned.</div>'}<div class="divider" style="margin:14px 0"></div><div class="row small ${p.validation?.valid?'muted':''}">${icon(p.validation?.valid?'checkcircle':'warning')}${p.validation?.valid?'Structural validation passed':'Validation needs attention'}</div>${(p.validation?.issues||[]).map(i=>`<p class="small">${esc(i.message||i)}</p>`).join('')}<div class="row" style="margin-top:14px"><button class="btn primary sm" data-action="apply-plan" ${p.operations?.length&&p.validation?.valid?'':'disabled'} ${disabledEdit()}>${icon('check')}Apply ${p.operations?.length||0} changes</button><button class="btn subtle sm" data-action="discard-plan">Discard</button></div><p class="small" style="margin-top:13px;font-size:9px;color:#9aa7b9">Provider: ${esc(p.provider)}. Applied changes remain a draft.</p></div></div>`;}
