function connectionReady(connection){return ['ready','connected','healthy'].includes(String(connection?.status||'').toLowerCase());}
function connectionStatusClass(status){return connectionReady({status})?'green':['revoked','failed','unreachable','error'].includes(String(status||'').toLowerCase())?'red':['draft','configuration_required','missing_credentials','degraded'].includes(String(status||'').toLowerCase())?'amber':'';}
async function loadConnectionCatalog(force=false){if(state.connectionCatalogLoading||state.connectionCatalogLoaded&&!force)return;if(preview){state.connectionCatalogLoaded=true;return;}state.connectionCatalogLoading=true;state.connectionCatalogError='';try{const response=await api('/api/integration-catalog'),providers=response.providers||response.connectionCatalog||response;if(!Array.isArray(providers))throw new Error('The integration catalog response is invalid.');state.data.connectionCatalog=providers;state.connectionCatalogLoaded=true;}catch(error){state.connectionCatalogLoaded=true;state.connectionCatalogError=error.message||'Integration catalog unavailable.';}finally{state.connectionCatalogLoading=false;if(state.route==='connections')render();}}
