function connectionProvisioningAvailable(provider){const capability=state.data.capabilities?.connections?.provision??state.data.capabilities?.connectionProvisioning,id=normalizeConnectionProviderId(provider?.id);if(id==='generic-rest'&&provider?.setup?.reviewedImportEnabled!==true)return false;if(id==='mcp'&&provider?.setup?.clientImplemented!==true)return false;return provider?.available===true&&(provider?.setup?.enabled===true||capability===true||capability?.enabled===true);}
function connectionProviderIcon(provider){const value=String(provider?.id||provider?.providerId||provider?.type||'').toLowerCase();return provider?.icon||(/jira|ticket/.test(value)?'ticket':/confluence|knowledge/.test(value)?'book':/slack/.test(value)?'activity':/webhook/.test(value)?'bolt':/rest|openapi/.test(value)?'code':'plug');}
function connectionEffectLabel(value){const effect=String(value||'declared').toLowerCase();return effect==='write'?'Writes require review':effect==='mixed'?'Read + write operations':effect==='read'?'Read only':human(effect);}
function connectionCard(connection){const operations=connectionOperations(connection),scopes=connectionScopes(connection),ready=connectionReady(connection),credentialsAvailable=connection.auth?.credentialsAvailable,refsConfigured=connection.auth?.credentialReferencesConfigured,localAuthority=ready&&/local/.test(connectionProviderId(connection)),authorityLabel=credentialsAvailable===true?'Credentials available':credentialsAvailable===false&&refsConfigured?'References saved · values unavailable':localAuthority?'Local authority ready':credentialsAvailable===false?'Credentials unavailable':'Authority reported by server',health=connection.health||{},effect=connection.sideEffects||([...new Set(operations.map(operation=>operation.effect))].length>1?'mixed':operations[0]?.effect),declaredActions=connection.allowedActions||connection.actions,actions=Array.isArray(declaredActions)?declaredActions:null,canTest=!actions||actions.includes('test'),authorityAction=ready&&(!actions||actions.includes('revoke'))?'revoke':['draft','revoked','disabled','error'].includes(connection.status)&&actions?.includes('restore')?'restore':connection.status==='revoked'&&!actions?'restore':null,authorityActionLabel=authorityAction==='restore'&&connection.status==='draft'?'Activate':authorityAction==='restore'&&['revoked','disabled'].includes(connection.status)?'Restore to draft':human(authorityAction);return `<article class="connection-card integration-connection"><span class="node-icon ${effect==='write'||effect==='mixed'?'orange':'blue'}">${icon(connectionProviderIcon(connection))}</span><div class="flex connection-copy"><div class="row connection-title-row"><h3>${esc(connection.name||human(connection.id))}</h3><span class="pill ${connectionStatusClass(connection.status)}">${esc(human(connection.status||'unknown'))}</span></div><p>${esc(connection.description||connection.endpoint||'A registered adapter with a declared capability boundary.')}</p><div class="connection-facts"><span>${icon('shield')}${esc(authorityLabel)}</span><span>${icon('activity')}${esc(connectionEffectLabel(effect))}</span>${health.checkedAt?`<span>${icon('clock')}Checked ${esc(date(health.checkedAt))}</span>`:''}</div>${scopes.length?`<div class="connection-scopes" aria-label="Authorized scopes">${scopes.map(scope=>`<span>${esc(scope)}</span>`).join('')}</div>`:''}${operations.length?`<div class="connection-operations" aria-label="Allowed operations">${operations.slice(0,4).map(operation=>`<code>${esc(operation.id)}</code>`).join('')}${operations.length>4?`<span>+${operations.length-4} more</span>`:''}</div>`:''}${connection.activation?.eligible===false?`<p class="connection-activation-hint">${icon('clock')}${esc(connection.activation.reason||'Complete the connection checks before activation.')}</p>`:''}</div><div class="connection-state"><span class="pill">Generation ${Number(connection.generation)||1}</span><span class="pill">${esc(connection.mode||connection.type||connection.providerId||connection.provider||'Registered adapter')}</span><div class="row"><button class="btn subtle sm" data-connection-details="${esc(connection.id)}">Details</button>${canTest?`<button class="btn sm" data-connection-test="${esc(connection.id)}" ${role()==='admin'?'':'disabled title="Administrator role required"'}>Test health</button>`:''}${authorityAction?`<button class="btn sm ${authorityAction==='revoke'?'danger':''}" data-connection-action="${authorityAction}" data-connection-id="${esc(connection.id)}" ${role()==='admin'?'':'disabled title="Administrator role required"'}>${esc(authorityActionLabel)}</button>`:''}</div></div></article>`;}
function connectionCatalogCard(provider){const linked=connectionEntries().filter(connection=>connectionProviderId(connection)===provider.id),ready=linked.filter(connectionReady).length,available=connectionProvisioningAvailable(provider),canSetup=available&&role()==='admin',operations=connectionOperations(provider),limitation=provider.id==='generic-rest'?'Developer-reviewed import required':provider.id==='mcp'?'MCP client integration required':'Connector not installed';return `<article class="integration-catalog-card"><div class="integration-catalog-head"><span class="node-icon blue">${icon(connectionProviderIcon(provider))}</span><span><small>${esc(provider.category||'Integration')}</small><h3>${esc(provider.name||human(provider.id))}</h3></span><span class="pill ${ready?'green':available?'blue':''}">${ready?`${ready} connected`:available?'Setup available':limitation}</span></div><p>${esc(provider.description||'Connect a provider through a reviewed adapter package.')}</p><div class="connection-facts"><span>${icon('lock')}${esc((provider.authKinds||['Server managed']).join(' · '))}</span><span>${icon('activity')}${operations.length} declared operations</span></div><button class="btn ${canSetup?'primary':'subtle'} sm" data-connection-provider="${esc(provider.id)}">${canSetup?'Set up connection':'View requirements'}</button></article>`;}
function connectionsPage(){const connections=connectionEntries(),catalog=reportedConnectionCatalog(),ready=connections.filter(connectionReady).length,operationCount=connections.reduce((total,connection)=>total+connectionOperations(connection).length,0),writeCount=connections.filter(connection=>['write','mixed'].includes(connection.sideEffects)||connectionOperations(connection).some(operation=>operation.effect==='write')).length;return `<div class="content-page connections-page">${heading('Capability boundaries','Connections & adapters','Connect external systems without giving a model unrestricted credentials or authority. Every operation stays typed, scoped, observable, and revocable.')}<div class="connection-metrics" aria-label="Connection summary"><span><strong>${connections.length}</strong><small>Registered</small></span><span><strong>${ready}</strong><small>Ready</small></span><span><strong>${operationCount}</strong><small>Allowed operations</small></span><span><strong>${writeCount}</strong><small>Write-capable</small></span></div><div class="notice">${icon('lock')}<div><strong>Credentials stay server-side.</strong> Saved secrets are never returned to this page or exposed to an agent. A connection only grants the listed operations and scopes. Consequential writes use exact prepared-action review; uncertain remote outcomes stop for provider-specific or human reconciliation.</div></div><section class="connections-section"><div class="spread"><div><div class="eyebrow">Current environment</div><h2>Configured connections</h2></div><span class="pill">Server reported</span></div><div class="connections-grid">${connections.map(connectionCard).join('')||empty('No connections configured','Choose a provider below. Setup is enabled only when its server connector is installed.','plug')}</div></section><section class="connections-section"><div class="spread"><div><div class="eyebrow">Integration catalog</div><h2>Connect the systems your work already uses</h2><p>Slack, Atlassian, APIs, webhooks, and MCP all enter the same capability registry. Installing a connector does not automatically authorize its tools for any agent.</p></div><span class="pill">${state.connectionCatalogLoading?'Loading…':`${catalog.length} provider types`}</span></div>${state.connectionCatalogError?`<div class="info-box amber" style="margin-top:14px">Live catalog unavailable: ${esc(state.connectionCatalogError)} The built-in requirements guide remains visible, but no provider is presented as installable.</div>`:''}<div class="integration-catalog-grid">${catalog.map(connectionCatalogCard).join('')}</div></section><div class="surface connections-runtime"><div class="surface-head"><div><h3>Runtime capability report</h3><p>Raw server evidence for this environment—not a production-readiness claim.</p></div><span class="pill">Reported by server</span></div><div class="surface-body"><pre>${esc(JSON.stringify(state.data.capabilities||{},null,2))}</pre></div></div></div>`;}
function connectionOperationScopes(operation){const scopes=operation?.requiredScopes||operation?.scopes||[];return Array.isArray(scopes)?scopes:[];}
