function updateConnectionSetupAuthority(form){if(!form)return;const mode=form.querySelector('[data-connection-auth-mode]')?.value||'none';for(const wrapper of $$('[data-connection-auth-modes]',form)){const visible=wrapper.dataset.connectionAuthModes.split(',').includes(mode),field=wrapper.querySelector('[data-connection-field]');wrapper.hidden=!visible;if(field){field.disabled=!visible;field.required=visible&&field.dataset.connectionRequired==='true';}}const provider=reportedConnectionCatalog().find(item=>item.id===form.dataset.connectionSetupForm),operations=connectionOperations(provider),selected=new Set($$('[data-connection-operation]:checked',form).map(field=>field.dataset.connectionOperation)),scopes=[...new Set(operations.filter(operation=>selected.has(operation.id)).flatMap(connectionOperationScopes))],previewTarget=form.querySelector('[data-connection-scope-preview]');if(previewTarget)previewTarget.textContent=scopes.length?scopes.join(' · '):'No provider scopes required by the selected operations';}
