async function repairModal(){
  const d=await api(`/api/runs/${encodeURIComponent(state.run.id)}/repair`),retryPermission=d.safeToRetry?runActionPermission(state.run,'retry',d.proposal?.nodeId):{allowed:false,reason:'The diagnostic did not establish a safe retry.'};
  modal('Recovery diagnostic',`<div class="pill blue">Local diagnostic · deterministic</div><h3 style="margin:18px 0 10px">${esc(d.cause)}</h3><ul class="modal-list">${(d.evidence||[]).map(e=>`<li>${esc(e)}</li>`).join('')}</ul><div class="info-box ${d.safeToRetry?'green':'amber'}">${esc(d.proposal?.description||'Inspect the recorded inputs and outcomes before taking action.')}</div><p style="margin-top:15px">${d.safeToRetry?'The runtime considers the proposed retry safe under this adapter’s local idempotency contract.':'The diagnostic cannot establish that a retry is safe.'}</p>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-run-retry="${esc(d.proposal?.nodeId)}" ${retryPermission.allowed?'':`disabled title="${esc(retryPermission.reason)}"`}>${icon('repair')}Retry this step</button>`);
}
async function onAction(action,el){switch(action){
case'reload':location.reload();break;
case'close-modal':closeModal();break;
case'toggle-theme':state.theme=applyTheme(state.theme==='dark'?'light':'dark');render();toast(`${state.theme==='dark'?'Night':'Day'} mode enabled.`);break;
case'palette':if(state.palette){state.palette=false;state.pendingPlacement=null;}else{state.palette=true;state.pendingPlacement=null;}state.contextMenu=null;render();if(state.palette)$('#palette-search')?.focus();break;
case'toggle-inspector':state.mobilePanel=!state.mobilePanel;if(window.innerWidth>880){state.inspectorCollapsed=!state.inspectorCollapsed;}render();break;
case'assistant':state.panel='assistant';state.selected=null;state.mobilePanel=true;state.inspectorCollapsed=false;render();break;
case'fit':fitCanvas();break;
case'zoom-in':zoomTo(state.zoom*1.2);break;
case'zoom-out':zoomTo(state.zoom/1.2);break;
case'undo':if(state.undo.length){state.redo.push(snapshot());restoreSnapshot(state.undo.pop());}break;
case'redo':if(state.redo.length){state.undo.push(snapshot());restoreSnapshot(state.redo.pop());}break;
case'save':await saveTemplate();break;
case'validate':await validateTemplate();break;
case'close-to-lab':closeModal();setRoute('lab');break;
case'role-preview':rolePreview();break;
case'rename':modal('Workflow details',`<div class="field"><label for="template-name">Name</label><input id="template-name" value="${esc(state.template.name)}" maxlength="120"></div><div class="field"><label for="template-description">Description</label><textarea id="template-description" rows="3">${esc(state.template.description||'')}</textarea></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-rename">Update draft</button>`);break;
case'confirm-rename':{const name=$('#template-name').value.trim();if(!name)throw new Error('Enter a workflow name.');if(beginEdit()){state.template.name=name;state.template.description=$('#template-description').value.trim();closeModal();render();}}break;
case'confirm-node-rename':{const name=$('#context-node-label').value.trim();if(!name)throw new Error('Enter a step name.');if(beginEdit()){const node=state.template.nodes.find(item=>item.id===state.selected);if(!node)throw new Error('That workflow step no longer exists.');node.label=name;closeModal();render();toast('Step renamed in this draft.');}}break;
case'add-edge':modal('Connect two steps',`<p>The destination will wait for the source to succeed. Every incoming connection is required.</p><div class="field"><label for="edge-source">Source step</label><select id="edge-source">${state.template.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></div><div class="field"><label for="edge-target">Destination step</label><select id="edge-target">${state.template.nodes.map((n,i)=>`<option value="${esc(n.id)}" ${i===1?'selected':''}>${esc(n.label)}</option>`).join('')}</select></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-edge">Connect steps</button>`);break;
case'confirm-edge':addEdge($('#edge-source').value,$('#edge-target').value);closeModal();break;
case'delete-node':modal('Remove this step?',`<p>Removing <strong>${esc(state.template.nodes.find(n=>n.id===state.selected)?.label)}</strong> also removes its incoming and outgoing connections. You can undo this draft change.</p>`,`<button class="btn" data-action="close-modal">Keep step</button><button class="btn danger" data-action="confirm-delete-node">Remove step</button>`);break;
case'confirm-delete-node':if(beginEdit()){state.template.nodes=state.template.nodes.filter(n=>n.id!==state.selected);state.template.edges=state.template.edges.filter(e=>e.source!==state.selected&&e.target!==state.selected);state.selected=null;state.panel='assistant';closeModal();render();}break;
case'input-mapping':mappingModal();break;
case'save-mapping':{const mapping={};for(const el of $$('[data-map-field]')){const value=el.value.trim();if(value)mapping[el.dataset.mapField]=value;}if(beginEdit()){state.template.nodes.find(n=>n.id===state.selected).config.inputMapping=mapping;closeModal();render();toast('Input bindings updated in this draft. Validate to check upstream references.');}}break;
case'control-config':controlConfigModal();break;
case'save-control-config':{
  const node=state.template.nodes.find(item=>item.id===state.selected),kind=controlKind(node);
  const raw=kind==='condition'?{rule:$('#control-rule').value,mergeId:$('#control-merge').value}:
    kind==='parallel'?{joinId:$('#control-join').value}:
    kind==='join'?{joinMode:$('#control-join-mode').value}:
    {outcome:$('#control-outcome-status').value,reason:$('#control-outcome-reason').value};
  const patch=normalizeControlConfig(kind,raw);
  let branches=null;
  if(kind==='condition'&&$('#control-match-target')){
    const match=$('#control-match-target').value,fallback=$('#control-default-target').value;
    if(!match||!fallback||match===fallback)throw new Error('Choose two different condition branches.');
    branches={match,fallback};
  }
  if(beginEdit()){
    node.config={...(node.config||{}),...patch};
    if(branches)for(const edge of state.template.edges.filter(item=>item.source===node.id)){
      if(edge.target===branches.match)edge.branch='match';
      else if(edge.target===branches.fallback)edge.branch='default';
      else delete edge.branch;
    }
    closeModal();render();toast('Control policy updated. Validate the complete graph before release.');
  }
}break;
case'node-evidence':inspectAgent(state.template.nodes.find(n=>n.id===state.selected).agentId);break;
case'plan':{state.intent=$('#intent-input')?.value||state.intent;if(!state.intent.trim())throw new Error('Describe the change you want to propose.');if(state.dirty)await saveTemplate(true);state.proposal=await api('/api/plan',{method:'POST',body:{templateId:templateId(),intent:state.intent}});render();toast('Proposal ready. Inspect the operations and assumptions before applying.');}break;
case'apply-plan':{const t=await api(`/api/plan/${encodeURIComponent(state.proposal.id)}/apply`,{method:'POST',body:{expectedRevision:state.template.draftRevision}});setTemplate(t);state.proposal=null;render();toast('The reviewed proposal was applied to the draft.');}break;
case'discard-plan':state.proposal=null;render();break;
case'start-run':if(state.route==='studio'&&state.template?.status==='archived')throw new Error('Restore this archived template before starting a task.');state.runStartKey=newIdempotencyKey();startRunModal();break;
case'new-schedule':if(role()!=='admin')throw new Error('Administrator role required.');scheduleModal(null,state.route==='studio'?templateId():null);break;
case'save-schedule':await saveScheduleFromModal(el);break;
case'refresh-schedules':await refreshSchedules();break;
case'find-template':{const query=$('#template-query').value.trim(),response=await api(`/api/templates/find?q=${encodeURIComponent(query)}`),matches=response.matches||[],target=$('#template-matches');target.innerHTML=matches.length?matches.map(match=>`<button class="template-match" data-template-match="${esc(match.template_id)}"><span><strong>${esc(match.name||match.template_id)}</strong><small>${esc(match.explanation||'Eligible published workflow')}</small></span><span class="pill">v${esc(match.published_version)}</span></button>`).join(''):'<p class="small muted">No eligible published template matched this description.</p>';break;}
case'confirm-run':{applyTaskFields();let input;try{input=JSON.parse($('#run-input').value);}catch{throw new Error('Task input must be valid JSON.');}if(!input||Array.isArray(input)||typeof input!=='object')throw new Error('Task input must be a JSON object.');const artifacts=await readTaskArtifacts();await startRun($('#run-mode').value,$('#run-scenario').value,input,$('#run-template').value,artifacts,state.runStartKey||newIdempotencyKey());}break;
case'upload-input':$('#input-file').click();break;
case'refresh-runs':await refreshRuns();break;
case'review-release':await reviewRelease();break;
case'submit-release':{const t=await api(`/api/templates/${encodeURIComponent(templateId())}/submit`,{method:'POST',body:{}});setTemplate(t);closeModal();render();toast('Candidate submitted. A different reviewer can publish it.');}break;
case'publish-release':{const t=await api(`/api/templates/${encodeURIComponent(templateId())}/publish`,{method:'POST',body:{}});setTemplate(t);closeModal();render();toast('Published. New fixture runs use this immutable version.');}break;
case'duplicate-template':{if(state.dirty)throw new Error('Save or discard draft changes before duplicating this template.');const t=await api(`/api/templates/${encodeURIComponent(templateId())}/duplicate`,{method:'POST',body:{}});setTemplate(t);state.selected=null;state.panel='assistant';state.framingPending=true;render();toast('Independent draft copy created.');}break;
case'export-template':{if(preview)throw new Error('Template export requires the included local application.');const content=await api(`/api/templates/${encodeURIComponent(templateId())}/export`);const url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`axiom-template-${state.template.id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Validated template package exported.');}break;
case'import-template':modal('Import a template package',`<p>Select an Axiom template export. The server verifies its hash, registered agents, graph, mappings, and approval boundaries before creating a new draft.</p><div class="field"><label for="template-import-file">Template JSON package</label><input id="template-import-file" type="file" accept=".json,application/json"></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-template-import">Verify & import</button>`);break;
case'confirm-template-import':{const file=$('#template-import-file')?.files?.[0];if(!file)throw new Error('Choose an Axiom template JSON package.');if(file.size>1000000)throw new Error('Template packages must be smaller than 1 MB.');let content;try{content=JSON.parse(await file.text());}catch{throw new Error('The selected template package is not valid JSON.');}const t=await api('/api/templates/import',{method:'POST',body:content});setTemplate(t);state.selected=null;state.panel='assistant';state.framingPending=true;closeModal();setRoute('studio');toast('Template verified and imported as a new draft.');}break;
case'archive-template':modal('Archive this template?',`<p>New tasks and rehearsals will be blocked. Existing runs and published release history remain available. You can restore the template later.</p>`,`<button class="btn" data-action="close-modal">Keep active</button><button class="btn danger" data-action="confirm-archive-template">Archive template</button>`);break;
case'confirm-archive-template':{if(state.dirty)throw new Error('Save or discard draft changes before archiving this template.');const t=await api(`/api/templates/${encodeURIComponent(templateId())}/archive`,{method:'POST',body:{}});setTemplate(t);closeModal();render();toast('Template archived. Existing runs remain unchanged.');}break;
case'restore-template':{const t=await api(`/api/templates/${encodeURIComponent(templateId())}/restore`,{method:'POST',body:{}});setTemplate(t);render();toast('Template restored.');}break;
case'new-template':modal('Create a workflow template',`<p>Start with an empty, unpublished graph. Add reusable agents, map their inputs, and define the required decisions.</p><div class="field"><label for="new-template-name">Template name</label><input id="new-template-name" placeholder="Supplier onboarding" maxlength="120"></div><div class="field"><label for="new-template-description">Business purpose</label><textarea id="new-template-description" rows="3" placeholder="Describe the outcome this process should create."></textarea></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-new-template">Create blank template</button>`);break;
case'confirm-new-template':{const name=$('#new-template-name').value.trim();if(!name)throw new Error('Enter a template name.');const t=await api('/api/templates',{method:'POST',body:{name,description:$('#new-template-description').value.trim()}});setTemplate(t);state.selected=null;state.proposal=null;state.panel='assistant';state.pendingPlacement={x:90,y:225};state.palette=true;state.framingPending=true;state.inspectorCollapsed=false;closeModal();setRoute('studio');requestAnimationFrame(()=>$('#palette-search')?.focus());toast('Workflow created. Choose its first step.');}break;
case'new-agent':modal('Register a reusable agent',`<p>Create a named capability backed by an existing local implementation. Arbitrary code upload is intentionally unavailable in this reference runtime.</p><div class="field"><label for="agent-name">Agent name</label><input id="agent-name" placeholder="Case enrichment specialist"></div><div class="field"><label for="agent-description">Description</label><textarea id="agent-description" rows="3" placeholder="Explain the business capability and expected output."></textarea></div><div class="field"><label for="agent-implementation">Local implementation</label><select id="agent-implementation">${state.data.agents.filter(a=>['intake','csr','policy','ownership','approval','ticket','receipt','enrich'].includes(a.id)).map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.sideEffects)} side effects</option>`).join('')}</select></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-agent">Register agent</button>`);break;
case'confirm-agent':{const name=$('#agent-name').value.trim();if(!name)throw new Error('Enter an agent name.');const a=await api('/api/agents',{method:'POST',body:{name,description:$('#agent-description').value.trim(),implementationId:$('#agent-implementation').value}});state.data.agents.push(a);closeModal();render();toast('Agent registered and available in the step palette.');}break;
case'experiment':{if(state.template?.status==='archived')throw new Error('Restore this archived template before rehearsing it.');if(state.dirty)await saveTemplate(true);const e=await api('/api/experiments',{method:'POST',body:{templateId:templateId(),suite:'required'}});toast(`Required rehearsal suite started with ${(e.runs||[]).length} actual simulations.`);await refreshRuns();await loadExperiments();}break;
case'simulation-start':await simulationStartGuided();break;
case'simulation-reset':if(confirm('Reset this sandbox mirror to its recorded baseline? The workflow run and audit history remain available.'))await simulationResetWorld();break;
case'run-graph-in':state.runZoom=Math.min(1.25,(state.runZoom||.8)*1.15);render();break;
case'run-graph-out':state.runZoom=Math.max(.3,(state.runZoom||.8)/1.15);render();break;
case'run-graph-fit':{const t=runGraph(state.run),v=$('#runtime-graph-view');if(t?.nodes?.length&&v){const maxX=Math.max(...t.nodes.map(n=>(Number(n.x)||0)+250),500);state.runZoom=Math.min(1,(v.clientWidth-24)/maxX);render();}}break;
case'run-evidence':await evidenceModal();break;
case'run-effects':await effectsModal();break;
case'run-repair':await repairModal();break;
case'cancel-run':modal('Cancel this run?',`<p>New work will stop. Completed steps and their evidence remain recorded. This does not undo previous actions.</p>`,`<button class="btn" data-action="close-modal">Keep running</button><button class="btn danger" data-action="confirm-cancel-run">Cancel run</button>`);break;
case'confirm-cancel-run':await runAction('cancel',undefined);break;
case'export-run':{if(preview)throw new Error('Export requires the included local application.');const content=await api(`/api/runs/${encodeURIComponent(state.run.id)}/export`,{method:'POST',body:{}});const url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`axiom-run-${state.run.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Run export prepared and audited.');}break;
case'refresh-audit':await loadAudit();break;
case'about':modal('Axiom · local reference application',`<p>A working reference for governed workflows and reusable Goal Agents. Deterministic workflow controls, adaptive sessions, exact-action review, evidence, and rehearsals remain visibly separated from external production integrations.</p><div class="divider"></div><p><strong>Scope:</strong> One local workspace with development account switching. Scripted fixtures are labeled and do not claim model quality or external delivery. Configured-model execution never silently falls back to a script.</p><div class="divider"></div><p><strong>Keyboard:</strong> Tab to steps and controls. Enter selects a step. Ctrl/Cmd+Z undoes graph edits. Ctrl/Cmd+Shift+Z redoes. Escape closes dialogs and cancels connection mode.</p>`,`<button class="btn primary" data-action="close-modal">Continue</button>`);break;
}}

const FACTORY_API={catalog:'/api/agent-factory',specs:'/api/agent-specs',runs:'/api/agent-runs'};
function factoryState(){state.factory??={specs:[],tools:[],runs:[],scenarios:[],provider:{},selectedSpecId:null,specDraft:null,specDirty:false,schemaDrafts:{},run:null,selectedRunId:null,goal:'',inputText:'{}',mode:'fixture',tab:'configure',loading:false,loaded:false,error:null,proposal:null};return state.factory;}
function factoryModeLabel(mode){return mode==='model'||mode==='configured-model'?'Configured model':'Scripted fixture';}
function factoryCanEdit(){return role()==='admin';}
function factoryAdminDisabled(){return factoryCanEdit()?'':'disabled title="Administrator role required to author an agent"';}
function factoryTools(){return factoryState().tools||[];}
function factoryToolAuthority(tool){const binding=tool.adapterBinding||{},operation=binding.operation||tool.id,explicit=tool.connectionId||binding.connectionId,providerId=String(tool.providerId||binding.providerId||'').toLowerCase(),connections=connectionEntries(),connection=connections.find(item=>item.id===explicit)||connections.find(item=>providerId&&connectionProviderId(item)===providerId&&connectionOperations(item).some(candidate=>candidate.id===operation||candidate.id===tool.id))||connections.find(item=>connectionOperations(item).some(candidate=>candidate.id===operation||candidate.id===tool.id)),external=tool.verification?.externalIntegration===true||['http','https','mcp','webhook'].includes(String(binding.transport||'').toLowerCase());if(connection)return {label:connection.name||human(connection.id),status:connectionReady(connection)?'ready':connection.status||'unavailable',connection};if(external)return {label:providerId?human(providerId):binding.adapterId||'External adapter',status:'setup_required'};return {label:binding.adapterId||tool.verification?.environment||'Local capability',status:tool.verification?.status||'registered'};}
function factoryToolOption(tool,capabilities,editable){const authority=factoryToolAuthority(tool),scope=tool.authorization?.scope||tool.authorization?.scopes,scopeText=Array.isArray(scope)?scope.join(', '):scope,effect=tool.effect||'read',stateClass=authority.status==='ready'?'green':['setup_required','revoked','unavailable','failed'].includes(authority.status)?'amber':'';return `<label class="factory-tool-option"><input type="checkbox" data-factory-tool="${esc(tool.id)}" ${capabilities.includes(tool.id)?'checked':''} ${editable}><span class="factory-tool-description"><strong>${esc(tool.name||tool.label||tool.id)}</strong><small>${esc(tool.description||'No business description was provided.')}</small><span class="factory-tool-authority"><span class="pill ${stateClass}">${esc(human(authority.status))}</span><span>${icon('plug')}${esc(authority.label)}</span>${scopeText?`<span>${icon('lock')}${esc(scopeText)}</span>`:''}</span><code>${esc(tool.id)}${tool.version?` · v${esc(tool.version)}`:''}</code></span><button type="button" class="pill ${effect==='write'?'amber':''}" data-factory-tool-info="${esc(tool.id)}" aria-label="Inspect ${esc(tool.id)} capability contract">${esc(effect)}</button></label>`;}
function factorySelectedSpec(){return factoryState().specs.find(spec=>spec.id===factoryState().selectedSpecId);}
function factorySpecName(run){return run?.specName||run?.specSnapshot?.name||factoryState().specs.find(spec=>spec.id===run?.specId)?.name||'Goal Agent run';}
function factoryRunStatus(run){return run?.status||run?.state?.status||'ready';}
function factoryRunState(run){return run?.state||run||{};}
function factoryStatus(status){const label={ready:'Ready',awaiting_tool:'Using a tool',awaiting_approval:'Review action',awaiting_input:'Needs clarification',completed:'Completed',stopped:'Stopped',failed:'Failed',rejected:'Rejected',cancelled:'Cancelled',running:'Running',planning:'Planning'}[status]||human(status);const color={ready:'',awaiting_tool:'blue',awaiting_approval:'amber',awaiting_input:'amber',completed:'green',stopped:'',failed:'red',rejected:'red',cancelled:'',running:'blue',planning:'blue'}[status]||'';return `<span class="pill ${color}"><span class="dot"></span>${esc(label)}</span>`;}
function factoryProviderConfigured(){const provider=factoryState().provider;return Boolean(provider.configured??provider.modelConfigured??state.data?.capabilities?.modelConfigured);}
function factorySpecUsage(spec){return (factoryState().runs||[]).filter(run=>run.specId===spec.id).length;}
function factoryPage(){
  const f=factoryState();
  if(!f.loaded)return `<div class="content-page">${heading('Goal-directed work','Agent Factory','Define what an agent should achieve, what it may read and do, what it must return, and when it must pause.')}${empty(f.loading?'Opening Agent Factory…':'Agent Factory',f.error||'Loading the local capability catalog and saved specifications.','spark',f.loading?'':`<button class="btn primary" data-action="factory-refresh">Open workspace ${icon('arrow')}</button>`)}</div>`;
  const draft=f.specDraft,provider=factoryProviderConfigured();
  return `<div class="factory-page"><header class="factory-header"><div><div class="eyebrow">Reusable adaptive agents</div><h1>Agent Factory</h1><p>Keep the mission stable. Let each session change its next step when the evidence changes.</p></div><div class="row factory-header-actions"><button class="factory-provider" data-action="factory-provider-info"><span class="dot ${provider?'connected':''}"></span><span>${provider?'Configured model available':'Model provider not configured'}</span>${icon('chevron')}</button><button class="btn" data-action="factory-brief" ${!provider?'disabled title="Configure a model provider to draft agents from a brief"':factoryAdminDisabled()}>${icon('spark')}Draft from brief</button><button class="btn" data-action="factory-new" ${factoryAdminDisabled()}>${icon('plus')}New agent</button><button class="btn primary" data-action="factory-save" ${!draft||!f.specDirty?'disabled':factoryAdminDisabled()}>${icon('save')}${f.specDirty?'Save new version':'Specification saved'}</button></div></header><div class="factory-view-tabs" role="tablist" aria-label="Agent Factory workspace"><button class="tab ${f.tab==='configure'?'active':''}" data-factory-tab="configure" role="tab" aria-selected="${f.tab==='configure'}">${icon('settings')}Configure</button><button class="tab ${f.tab==='execute'?'active':''}" data-factory-tab="execute" role="tab" aria-selected="${f.tab==='execute'}">${icon('play')}Try & inspect</button></div><div class="factory-layout factory-tab-${f.tab}"><aside class="factory-spec-rail" aria-label="Saved Goal Agents"><div class="spread"><span class="uppercase muted">Goal Agents</span><span class="pill">${f.specs.length}</span></div>${f.specs.map(spec=>`<button class="factory-spec-item ${spec.id===f.selectedSpecId?'active':''}" data-factory-spec="${esc(spec.id)}" aria-pressed="${spec.id===f.selectedSpecId}"><span class="factory-spec-icon">${icon('spark')}</span><span><strong>${esc(spec.name)}</strong><small>v${esc(spec.version||1)} · ${(spec.allowedTools||[]).length} capabilities · ${factorySpecUsage(spec)} runs</small></span></button>`).join('')||'<p class="field-hint factory-rail-empty">No saved Goal Agents yet.</p>'}<button class="factory-add" data-action="factory-new" ${factoryAdminDisabled()}>${icon('plus')}Create a custom specification</button><div class="factory-rail-note">${icon('shield')}<p>One shared runtime.<br>Each version pins its own authority and contracts.</p></div></aside><section class="factory-spec-pane">${draft?factorySpecEditor(draft):empty('Define a new Goal Agent','Create a specification to give it a mission, context boundary, capabilities, result contract, and limits.','agent')}</section><aside class="factory-run-pane">${factoryRunComposer()}<div id="factory-run-result">${factoryRunView()}</div><div id="factory-behavior-preview">${factoryBehaviorPreview()}</div></aside></div></div>`;
}
