async function factoryAnswer(){const f=factoryState(),answers={};for(const element of $$('[data-factory-answer-field]')){const raw=element.value.trim(),type=element.dataset.answerType;if(!raw)continue;let value=raw;if(type==='number'||type==='integer'){value=Number(raw);if(!Number.isFinite(value)||(type==='integer'&&!Number.isInteger(value)))throw new Error(`${element.dataset.factoryAnswerField} needs a valid ${type}.`);}else if(type==='boolean')value=raw==='true';else if(type==='array'||type==='object'){try{value=JSON.parse(raw);}catch{throw new Error(`${element.dataset.factoryAnswerField} needs valid JSON.`);}if(type==='array'?!Array.isArray(value):!value||Array.isArray(value)||typeof value!=='object')throw new Error(`${element.dataset.factoryAnswerField} needs a JSON ${type}.`);}answers[element.dataset.factoryAnswerField]=value;}if(!Object.keys(answers).length)throw new Error('Answer at least one requested field.');const response=await api(`${FACTORY_API.runs}/${encodeURIComponent(f.run.id)}/clarify`,{method:'POST',body:{answers}});f.run=response.run||response;f.runs=f.runs.map(run=>run.id===f.run.id?f.run:run);render();toast('Information recorded. The session can resume from the new observation.');}
async function factoryAction(action){const f=factoryState();switch(action){case'factory-brief':factoryBriefModal();break;case'factory-propose':await factoryPropose();break;case'factory-load-proposal':factoryLoadProposal();break;case'factory-refresh':await loadFactory(true);break;case'factory-new':factoryNew();break;case'factory-save':await factorySave();break;case'factory-publish':await factoryPublish();break;case'factory-start':await factoryStart();break;case'factory-refresh-run':await factoryRefreshRun();break;case'factory-clear-run':f.run=null;f.selectedRunId=null;render();break;case'factory-review-action':factoryActionModal('approve');break;case'factory-reject-action':factoryActionModal('reject');break;case'factory-answer':await factoryAnswer();break;case'factory-stop-run':{const response=await api(`${FACTORY_API.runs}/${encodeURIComponent(f.run.id)}/stop`,{method:'POST',body:{}});f.run=response.run||response;f.runs=f.runs.map(run=>run.id===f.run.id?f.run:run);render();toast('Session stopped. Completed effects remain recorded.');}break;case'factory-run-json':modal('Complete Goal Agent session record',`<pre>${esc(JSON.stringify(f.run,null,2))}</pre>`,`<button class="btn primary" data-action="close-modal">Done</button>`,true);break;case'factory-provider-info':modal('Decision providers',`<div class="factory-provider-explainer"><article><span class="pill amber">Scripted fixture</span><h3>Deterministic runtime demonstration</h3><p>Exercises the adaptive loop, validation, persistence, questions, and approvals using declared decisions. It does not call AI or establish model quality.</p></article><article><span class="pill blue">Configured model</span><h3>Dynamic bounded decisions</h3><p>Sends the mission, permitted context, observations, contracts, and remaining budget to the configured provider. Missing configuration is shown as an error; no fixture fallback is used.</p></article></div><div class="section-label">Server-reported provider state</div><pre>${esc(JSON.stringify(f.provider,null,2))}</pre>`,`<button class="btn primary" data-action="close-modal">Done</button>`,true);break;}}
function factoryFacts(run){const runtime=factoryRunState(run),facts=runtime.facts||{};return Array.isArray(facts)?facts:Object.entries(facts).map(([id,value])=>({id,value,...(runtime.factSources?.[id]||{})}));}
function factoryInputField(run,path){let schema=run.specSnapshot?.inputSchema||factoryState().specs.find(spec=>spec.id===run.specId)?.inputSchema||{};for(const part of path.replace(/^input\./,'').split('.'))schema=schema.properties?.[part]||{};return schema;}
function factoryBridgeEditor(node,manifest){const f=factoryState(),specId=manifest.factorySpecId||node.config?.factorySpecId||'',version=manifest.factorySpecVersion||manifest.version||1,mode=node.config?.factoryMode||manifest.defaultFactoryMode||'model',fixtureEnabled=manifest.fixtureEnabled===true;if(!f.loaded&&!f.loading)queueMicrotask(()=>loadFactory());const spec=f.specs.find(item=>item.id===specId);return `<div class="factory-bridge"><div class="spread"><h3>Goal Agent placement</h3><span class="pill blue">Adaptive child session</span></div><p class="field-hint">This node starts or resumes one durable child session. The parent waits for a typed result, a clarification, or an exact-action decision.</p><div class="factory-pinned-spec"><span>${icon('lock')}</span><div><strong>${esc(spec?.name||manifest.name||specId)}</strong><small><code>${esc(specId)}</code> · approved version ${esc(version)}</small></div></div><p class="field-hint">The specification and capability contracts are pinned by the selected palette entry. Replace this node from the palette to adopt another version.</p><div class="field"><label for="bridge-mode">Decision provider</label><select id="bridge-mode" data-config="factoryMode" ${disabledEdit()}><option value="fixture" ${mode==='fixture'?'selected':''} ${fixtureEnabled?'':'disabled'}>Scripted fixture · ${fixtureEnabled?'labeled demo':'unavailable for this version'}</option><option value="model" ${mode==='model'?'selected':''}>Configured model · no fallback</option></select></div>${fixtureEnabled?`<div class="field"><label for="bridge-scenario">Fixture variation</label><select id="bridge-scenario" data-config="factoryScenario" ${disabledEdit()}><option value="">Choose a fixture case…</option>${(f.scenarios||[]).filter(scenario=>scenario.specId===specId).map(scenario=>`<option value="${esc(scenario.id)}" ${node.config?.factoryScenario===scenario.id?'selected':''}>${esc(scenario.name||scenario.label||scenario.id)}</option>`).join('')}</select></div>`:''}<div class="field"><label for="bridge-goal">Case-specific objective</label><textarea id="bridge-goal" rows="3" data-config="goal" placeholder="Use the saved mission, or narrow it for this workflow placement." ${disabledEdit()}>${esc(node.config?.goal||'')}</textarea></div><button class="btn sm" data-open-factory-spec="${esc(specId)}" style="width:100%" ${specId?'':'disabled'}>${icon('spark')}Open saved specification</button><div class="field-hint" style="margin-top:12px">A node-level start approval never approves a consequential action discovered later inside the child session.</div></div>`;}
async function openFactorySpec(id){setRoute('factory');await loadFactory();if(id)factorySelectSpec(id);}
function factoryBriefModal(){if(!factoryProviderConfigured())throw new Error('Configure a compatible model provider before drafting an agent from a brief.');modal('Draft a Goal Agent from a brief',`<p>Describe the responsibility, permitted information, expected result, and when a person must decide. The configured model may propose only capabilities registered by this server. Nothing is saved or authorized automatically.</p><div class="field"><label for="factory-brief">Business request</label><textarea id="factory-brief" rows="7" placeholder="Build an agent that investigates onboarding problems. It may inspect the account and existing cases, must request missing identity evidence, and may prepare—but not execute—a new work item. Return an evidence-backed recommendation."></textarea></div><div class="info-box">The proposal must pass the same allowlist, strict schemas, context projection, and resource-limit checks as a manually authored specification.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="factory-propose">${icon('spark')}Generate a reviewable proposal</button>`);}
async function factoryPropose(){const brief=$('#factory-brief')?.value.trim();if(!brief)throw new Error('Describe the agent you want to create.');const result=await api(`${FACTORY_API.specs}/propose`,{method:'POST',body:{brief}}),f=factoryState(),proposal=result.proposal||result,spec=proposal.spec||result.spec||{};f.proposal={...proposal,spec};modal('Review the proposed Goal Agent',`<div class="spread"><h3>${esc(spec.name||'Proposed specification')}</h3><span class="pill blue">${esc(proposal.provider?.label||proposal.provider||'Configured-model proposal')}</span></div><p style="margin-top:16px">${esc(spec.mission||'')}</p><div class="section-label">Requested capability allowlist</div><p>${(spec.allowedTools||[]).map(tool=>`<span class="tag mono">${esc(tool)}</span>`).join('')||'No capabilities requested'}</p><div class="section-label">Permitted context</div><p>${(spec.contextFields||[]).map(path=>`<span class="tag mono">${esc(path)}</span>`).join('')||'No context paths proposed'}</p><div class="info-box" style="margin-top:17px">Suggested permissions do not authorize themselves. Review the mission, instructions, contracts, capabilities, and limits before explicitly saving.</div><details class="factory-contract"><summary>Inspect complete proposed specification</summary><pre style="margin:0;border:0">${esc(JSON.stringify(spec,null,2))}</pre></details>`,`<button class="btn" data-action="close-modal">Discard</button><button class="btn primary" data-action="factory-load-proposal">Load into editor · not saved</button>`,true);}
function factoryLoadProposal(){const f=factoryState();if(!f.proposal?.spec)throw new Error('No proposed specification is available.');if(f.specDirty&&!confirm('Replace the current unsaved specification with this proposal?'))return;const spec=clone(f.proposal.spec);for(const key of ['id','version','revision','agentId','publishedVersion','activeVersion','status'])delete spec[key];f.specDraft=spec;f.selectedSpecId=null;f.schemaDrafts={};f.jsonDrafts={};f.specDirty=true;f.proposal=null;f.scenarioId='';f.goal=spec.mission||'';f.inputText=JSON.stringify(exampleInputForSchema(spec.inputSchema),null,2);f.mode='model';f.run=null;f.selectedRunId=null;f.tab='configure';closeModal();render();toast('Model proposal loaded for human review. It is not saved or authorized yet.');}
