if(el.id==='input-file'&&el.files[0]){if(el.files[0].size>1000000)throw new Error('Use a JSON input file smaller than 1 MB.');const input=JSON.parse(await el.files[0].text());$('#run-input').value=JSON.stringify(input,null,2);decorateTaskInputForm(false);toast('Task input loaded. Inspect it before starting the run.');}
