document.addEventListener('keydown',e=>{
  const simulationTab=e.target.closest?.('[data-simulation-tab]');
  if(simulationTab&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){
    e.preventDefault();const tabs=$$('[data-simulation-tab]'),index=Math.max(0,tabs.indexOf(simulationTab)),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:e.key==='ArrowRight'?(index+1)%tabs.length:(index-1+tabs.length)%tabs.length;state.simulationTab=tabs[next].dataset.simulationTab;render();requestAnimationFrame(()=>$(`[data-simulation-tab="${CSS.escape(state.simulationTab)}"]`)?.focus());return;
  }
  const menu=e.target.closest?.('.context-menu');
  if(menu&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){
    e.preventDefault();const items=$$('.context-menu-item:not(:disabled)',menu);if(!items.length)return;const index=Math.max(0,items.indexOf(document.activeElement));const next=e.key==='Home'?0:e.key==='End'?items.length-1:e.key==='ArrowDown'?(index+1)%items.length:(index-1+items.length)%items.length;items[next].focus();return;
  }
  if(e.key==='Escape'){
    if(state.contextMenu){e.preventDefault();closeContextMenu();return;}
    if(!closeModal())return;state.linkFrom=null;state.palette=false;state.pendingPlacement=null;state.mobilePanel=false;if(state.route==='studio')render();return;
  }
  const isField=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName||''),modifier=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();
  if(modifier&&key==='s'&&!isField&&state.route==='studio'){e.preventDefault();onAction('save').catch(error=>toast(error.message,true));return;}
  if(modifier&&key==='d'&&!isField&&state.route==='studio'&&state.selected&&canEdit()){
    e.preventDefault();try{const copy=duplicateNodeInDraft(state.selected);if(copy){render();ensureNodeVisible(copy.id);toast('Step duplicated without copying its connections.');}}catch(error){toast(error.message,true);}return;
  }
  if(modifier&&key==='z'&&!isField&&state.route==='studio'){e.preventDefault();onAction(e.shiftKey?'redo':'undo').catch(error=>toast(error.message,true));return;}
  if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('.runtime-node[data-step-data]')){e.preventDefault();e.target.click();}
  if(e.key==='Enter'&&e.target.dataset?.openRun)setRoute('runs',e.target.dataset.openRun);
  if(e.key==='Tab'&&$('.modal')){const focusable=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]',$('.modal'));if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
