async function boot(){try{state.data=await api('/api/bootstrap');state.data.users=state.data.users||[state.data.user];state.data.agents=state.data.agents||[];state.data.runs=state.data.runs||[];state.data.schedules=state.data.schedules||[];state.data.templates=state.data.templates||[];if(!state.data.templates[0])throw new Error('No workflow template was returned by the server.');state.template=await api(`/api/templates/${encodeURIComponent(state.data.templates[0].id)}`);const [r,id]=location.hash.slice(1).split('/');state.route=nav.some(n=>n[0]===r)?r:(state.data.preview?.startRoute||'studio');state.runId=id||null;if(state.route==='runs'&&id)state.run=await api(`/api/runs/${encodeURIComponent(id)}`);render();if(state.route==='schedules')refreshSchedules(true);if(state.route==='lab')loadExperiments();if(state.route==='audit')loadAudit();if(state.route==='factory')loadFactory();if(!preview)setInterval(async()=>{if(document.hidden||$('#modal-root').children.length||state.polling)return;if(state.route==='factory'&&state.factory?.selectedRunId){if(document.activeElement?.hasAttribute?.('data-factory-answer-field'))return;state.polling=true;try{await factoryRefreshRun();state.pollStale=false;state.pollError='';}catch(error){state.pollStale=true;state.pollError=error?.message||'The Goal Agent session could not be refreshed.';}finally{state.polling=false;}return;}const watching=['runs','review','lab','schedules'].includes(state.route);if(!watching&&!activeRuns().length)return;state.polling=true;try{const result=await api('/api/runs');state.data.runs=Array.isArray(result)?result:result.runs||[];if(state.route==='schedules'){const response=await api('/api/schedules');state.data.schedules=Array.isArray(response)?response:response.schedules||[];state.schedulesError='';}if(state.route==='runs'&&state.runId)state.run=await api(`/api/runs/${encodeURIComponent(state.runId)}`);if(state.route==='lab')state.experiments=await api(`/api/experiments?templateId=${encodeURIComponent(templateId())}`);const recovered=state.pollStale;state.pollStale=false;state.pollError='';if(watching||recovered)render();}catch(error){const firstFailure=!state.pollStale;state.pollStale=true;state.pollError=error?.message||'The local service is temporarily unavailable.';if(state.route==='schedules')state.schedulesError=state.pollError;if(firstFailure)render();}finally{state.polling=false;}},1800);}catch(e){$('#app').innerHTML=`<div class="boot"><div class="brand-symbol">a</div><h1>Workspace unavailable</h1><p class="muted" style="max-width:430px;line-height:1.8">${esc(e.message)}</p><button class="btn primary" data-action="reload">Try again</button></div>`;}}
